private static GameEngine.Level career1() {
GameEngine.Level l = new GameEngine.Level(1, 100, 500);
l.stage = 1; l.name = STAGE_NAMES[0]; l.stageId = "diner"; l.bgState = "state_0";
l.width = 16; l.height = 16;
l.tables.add(new GameEngine.Table(5, 6, new int[] {-1, -1}));
l.tables.add(new GameEngine.Table(12, 6, new int[] {-1, -1}));
l.drinkPosition = new int[] {14, 3}; l.podiumPosition = new int[] {1, 11};
l.kitchen = new int[] {5, 3};
l.bus = new int[] {15, 3};
l.foodPositions = new int[][] {new int[] {7, 3}, new int[] {9, 3}, new int[] {11, 3}};
l.snacks = new String[] {}; l.snackPercent = 0;
l.intro = "Welcome to my first diner! Only a couple of tables to start, but that's enough to get us going. Let's see if me can learn the basics with some standard customers.";
l.succeed = "Great work! Now we're ready for some real customers. Let's get some more tables in here.";
l.fail = "We didn't earn enough this shift.";
l.arrivals.add(new GameEngine.Arrival(0L, new int[] {0, 0}, "default_tutorial"));
l.arrivals.add(new GameEngine.Arrival(25000L, new int[] {0}, "default_tutorial"));
l.arrivals.add(new GameEngine.Arrival(25000L, new int[] {0, 0}, "default_tutorial"));
return l;
}
