public static GameEngine.Level endless(int stage, int difficulty) {
switch ((stage-1)*3 + difficulty) {
case 1: return endless1_1();
case 2: return endless1_2();
case 3: return endless1_3();
case 4: return endless2_1();
case 5: return endless2_2();
case 6: return endless2_3();
case 7: return endless3_1();
case 8: return endless3_2();
case 9: return endless3_3();
case 10: return endless4_1();
case 11: return endless4_2();
case 12: return endless4_3();
case 13: return endless5_1();
case 14: return endless5_2();
case 15: return endless5_3();
default: throw new IllegalArgumentException("Unknown endless setting");
}
}
